import org.intellij.lang.annotations.Language

fun render(@Language("HTML") body: String) = body

class Log {
    fun render(msg: String) = msg
}

fun f(log: Log, v: String) = log.render("user ${v} logged in")

import org.intellij.lang.annotations.Language

fun render(@Language("HTML") body: String) = body

class Log {
    fun render(msg: String) = msg

    fun f(v: String) = render("user ${v} logged in")
}

class Person(val name: String)

object Users {
    val ADMIN = Person(readLine()!!)
}

fun f() = "<p data-text=\"${Users.ADMIN.name}\">x</p>"
